# -*- coding: utf-8 -*-
"""MANAPRINT — Générateur AUSTRALES (A4 portrait, 15 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa maquette (bannière « AUSTRALES », la carte des Australes avec ses
   îles Rimatara · Rurutu · Tubuai · Raivavae · Rapa · Marotiri, les oiseaux,
   le cocotier, le coucher de soleil, les cinq cercles et le cadre).
   RIEN n'a ete redessine, rien ajoute, rien enleve : on se contente
   d'ECRIRE LES NUMEROS dans les cinq cercles. NE PAS « ameliorer ».

LA REGLE DU JEU : CINQ numeros sur TROIS colonnes seulement —
   B 1-15 (DEUX numeros, a gauche) · N 31-45 (UN, au centre-bas) ·
   O 61-75 (DEUX numeros, a droite).  Le crieur ne sort QUE 1-15, 31-45,
   61-75 (le 16-30 et le 46-60 n'existent pas sur ce jeu).

L'ARC-EN-CIEL EST CARTON PAR CARTON : la planche n'est gravee qu'une fois
   (un seul carton), puis reposee quinze fois, chaque fois dans la couleur de
   SON carton. En noir & blanc on la repose au gris #555555. Les chiffres
   gardent le gris de la maison impose par app.py.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

